(()=>{const poll=()=>document.querySelectorAll('[hx-trigger*="every"]').forEach(e=>{const m=e.getAttribute('hx-trigger').match(/every\s+(\d+)s/);if(!m||e.dataset.polling)return;e.dataset.polling='1';setInterval(()=>{let u=e.getAttribute('hx-get'),s=e.getAttribute('hx-include');if(s){const p=new URLSearchParams;document.querySelectorAll(s).forEach(n=>{if(n.name)p.append(n.name,n.value)});const q=p.toString();if(q)u+=(u.includes('?')?'&':'?')+q}fetch(u).then(r=>r.text()).then(t=>e.innerHTML=t).catch(()=>{})},Number(m[1])*1000)});poll()})();
